"use strict";(globalThis.webpackChunkgrc||=[]).push([[51030],{956(e){e.exports=JSON.parse('{"citeKey":"yang2014scaler","slug":"yang-2014-scaler-0d41","title":"SCALER: Scalable Parallel File Write in HDFS","authors":["X. Yang","Y. Yin","H. Jin","X.-H. Sun"],"venue":"International Conference on Cluster Computing 2014 (Cluster\'14), Madrid, Spain","type":"Conference","entryType":"inproceedings","date":"September, 2014","year":2014,"era":"iit","month":9,"doi":"10.1109/cluster.2014.6968736","abstract":"Two camps of file systems exist: parallel file systems designed for conventional high performance computing (HPC) and distributed file systems designed for newly emerged data- intensive applications. Addressing the big data challenge requires an approach that utilizes both high performance computing and data-intensive computing power. Thus, HPC applications may need to interact with distributed file systems, such as HDFS. The N-1 (N-to-1) parallel file write is a critical technical challenge, because it is very common for HPC applications but HDFS does not allow it. This study introduces a system solution, named SCALER, which allows MPI based applications to directly access HDFS without extra data movement. SCALER supports N-1 file write at both the inter-block level and intra-block level. Experimental results confirm that SCALER achieves the design goal efficiently.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2014/yang-2014-scaler-0d41.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["integrated-data-mgmt"],"memberAuthors":["sun-xian-he"]}')}}]);